public struct UtxoInfo {
    public var utxoId: Data
    public var valueHash: Data
    public var root: Data
    public var pathLen: UInt32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(utxoId: Data, valueHash: Data, root: Data, pathLen: UInt32) {
        self.utxoId = utxoId
        self.valueHash = valueHash
        self.root = root
        self.pathLen = pathLen
    }
}



extension UtxoInfo: Equatable, Hashable {
    public static func ==(lhs: UtxoInfo, rhs: UtxoInfo) -> Bool {
        if lhs.utxoId != rhs.utxoId {
            return false
        }
        if lhs.valueHash != rhs.valueHash {
            return false
        }
        if lhs.root != rhs.root {
            return false
        }
        if lhs.pathLen != rhs.pathLen {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(utxoId)
        hasher.combine(valueHash)
        hasher.combine(root)
        hasher.combine(pathLen)
    }
}


