public enum LightError {

    
    
    case Transport(String
    )
    case Rpc(code: Int64, message: String
    )
    case Parse(String
    )
    case UnknownRoot
    case BadPath
    case Hex(String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLightError: FfiConverterRustBuffer {
    typealias SwiftType = LightError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LightError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Transport(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .Rpc(
            code: try FfiConverterInt64.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Parse(
            try FfiConverterString.read(from: &buf)
            )
        case 4: return .UnknownRoot
        case 5: return .BadPath
        case 6: return .Hex(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LightError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Transport(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Rpc(code,message):
            writeInt(&buf, Int32(2))
            FfiConverterInt64.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Parse(v1):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .UnknownRoot:
            writeInt(&buf, Int32(4))
        
        
        case .BadPath:
            writeInt(&buf, Int32(5))
        
        
        case let .Hex(v1):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(v1, into: &buf)
            
        }
    }
}


extension LightError: Equatable, Hashable {}

extension LightError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}

